function dutch(s){s=sourceAliases[s]||s;s=s.replace(/([+−-]?[0-9]+)\.([0-9]+)(?=\s*s\b|%|×)/g,'$1,$2');s=s.replace(/\+(\d+) Laps?\b/g,(_,n)=>'+'+n+(n==='1'?' ronde':' ronden'));for(const [en,nl] of Object.entries(finishStatuses))if(s.endsWith(' · '+en))s=s.slice(0,-en.length)+nl;if(/^\+\d+ Laps?$/.test(s))return s.replace(/ Laps?$/,s.endsWith(' Laps')?' ronden':' ronde');if(reverseExact[s]!=null)return reverseExact[s];if(/^[+−-]?[0-9]+\.[0-9]+(?: s|%|×)?$/.test(s))return s.replace('.',',');let result=s;for(const [nl,en] of [...extraPhrases,...phrases].sort((a,b)=>b[1].length-a[1].length))result=result.split(en).join(nl);const reverseWords=[...words,['Pauzeren','Pause'],['Band','Tyre'],['Sector onbekend','Sector unknown']].sort((a,b)=>b[1].length-a[1].length);for(const [nl,en] of reverseWords)result=result.replace(new RegExp('(?<![\\p{L}])'+en.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'(?![\\p{L}])','gu'),nl);return result;}
function convert(node,key){const current=key==='text'?node.nodeValue:node.getAttribute(key);if(!current||!current.trim())return;let entry=memo.get(node);if(!entry){entry={};memo.set(node,entry);}let saved=entry[key];if(!saved||current!==saved.last)saved={source:current,last:current};const lead=saved.source.match(/^\s*/)[0],tail=saved.source.match(/\s*$/)[0];const next=lang==='en'?lead+english(saved.source.trim())+tail:lead+dutch(saved.source.trim())+tail;saved.last=next;entry[key]=saved;if(next!==current){if(key==='text')node.nodeValue=next;else node.setAttribute(key,next);}}
const observer=new MutationObserver(()=>apply());
function apply(){if(busy)return;busy=true;observer.disconnect();document.documentElement.lang=lang;const pageTitle=document.querySelector('title');if(pageTitle?.firstChild)convert(pageTitle.firstChild,'text');for(const el of document.querySelectorAll('[data-race-date]')){const date=new Date(el.getAttribute('datetime')+'T12:00:00Z');if(!Number.isNaN(date.getTime()))el.textContent=new Intl.DateTimeFormat(lang==='en'?'en-GB':'nl-NL',{day:'numeric',month:'long',year:'numeric',timeZone:'UTC'}).format(date);}const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);let node;while(node=walker.nextNode()){if(!node.parentElement?.closest('script,style,pre,code,[data-language-toggle],[data-race-date]'))convert(node,'text');}for(const el of document.querySelectorAll('[placeholder],[title],[aria-label],[aria-valuetext]')){if(el.closest('[data-language-toggle]'))continue;for(const key of ['placeholder','title','aria-label','aria-valuetext'])if(el.hasAttribute(key))convert(el,key);}const button=document.getElementById('language-toggle');if(button){button.setAttribute('aria-label',lang==='nl'?'Switch to English':'Schakel naar Nederlands');button.querySelectorAll('[data-lang]').forEach(el=>el.classList.toggle('active',el.dataset.lang===lang));}busy=false;observer.observe(document.body,{subtree:true,childList:true,characterData:true,attributes:true,attributeFilter:['placeholder','title','aria-label','aria-valuetext']});}
const button=document.getElementById('language-toggle');if(button)button.addEventListener('click',()=>{lang=lang==='nl'?'en':'nl';try{localStorage.setItem('overtake-it-away-language',lang);}catch{}apply();});
